package com.whistlesong.music

import kotlin.math.abs
import kotlin.math.floor
import kotlin.math.roundToInt

/** A single note on a beat grid. pitch is a MIDI note number. */
data class Note(
    val pitch: Int,
    val start: Double,     // in beats
    val duration: Double,  // in beats
    val velocity: Float = 0.85f,
    /** True if this note came from the user's whistle (vs. generated by the composer). */
    val fromUser: Boolean = false,
) {
    val end: Double get() = start + duration
}

enum class Mode(val intervals: IntArray, val label: String) {
    MAJOR(intArrayOf(0, 2, 4, 5, 7, 9, 11), "major"),
    MINOR(intArrayOf(0, 2, 3, 5, 7, 8, 10), "minor"),
}

private val NOTE_NAMES = arrayOf("C", "C#", "D", "Eb", "E", "F", "F#", "G", "Ab", "A", "Bb", "B")

fun noteName(midi: Int): String = NOTE_NAMES[((midi % 12) + 12) % 12] + (midi / 12 - 1)

data class Key(val tonic: Int, val mode: Mode) {
    /** Pitch class (0..11) of tonic. */
    val tonicPc: Int get() = ((tonic % 12) + 12) % 12

    val name: String get() = NOTE_NAMES[tonicPc] + " " + mode.label

    fun inScale(midi: Int): Boolean {
        val pc = ((midi - tonicPc) % 12 + 12) % 12
        return mode.intervals.contains(pc)
    }

    /**
     * Converts a "scale degree index" to MIDI. Degree 0 = tonic in octave 0 (MIDI tonicPc),
     * degree 7 = tonic one octave up, etc. Works for negatives too.
     */
    fun degreeToMidi(degree: Int): Int {
        val oct = Math.floorDiv(degree, 7)
        val idx = Math.floorMod(degree, 7)
        return tonicPc + 12 * oct + mode.intervals[idx]
    }

    /** Nearest scale degree index to a (possibly fractional) MIDI pitch. */
    fun midiToNearestDegree(midi: Double): Int {
        val approx = floor((midi - tonicPc) / 12.0 * 7.0).toInt()
        var best = approx
        var bestDist = Double.MAX_VALUE
        for (d in approx - 3..approx + 3) {
            val dist = abs(degreeToMidi(d) - midi)
            if (dist < bestDist) {
                bestDist = dist; best = d
            }
        }
        return best
    }

    /** Snap a fractional MIDI pitch to the nearest in-key note ("autotune"). */
    fun snap(midi: Double): Int = degreeToMidi(midiToNearestDegree(midi))
}

/** Diatonic triad (or seventh) built on a scale degree (0..6). */
data class Chord(val key: Key, val degree: Int, val seventh: Boolean = false) {
    /** Chord tones as scale degree indices relative to octave 0. */
    val degrees: List<Int>
        get() = if (seventh) listOf(degree, degree + 2, degree + 4, degree + 6)
        else listOf(degree, degree + 2, degree + 4)

    val pitchClasses: Set<Int>
        get() = degrees.map { Math.floorMod(key.degreeToMidi(it), 12) }.toSet()

    fun containsMidi(midi: Int) = pitchClasses.contains(Math.floorMod(midi, 12))

    fun rootMidiNear(target: Int): Int {
        val pc = Math.floorMod(key.degreeToMidi(degree), 12)
        var m = target - Math.floorMod(target - pc, 12)
        if (target - m > 6) m += 12
        return m
    }

    /** Chord tones voiced upward from a root near `rootTarget`. */
    fun voicing(rootTarget: Int): List<Int> {
        val root = rootMidiNear(rootTarget)
        val rootDeg = key.midiToNearestDegree(root.toDouble())
        val offs = if (seventh) listOf(0, 2, 4, 6) else listOf(0, 2, 4)
        return offs.map { key.degreeToMidi(rootDeg + it) }
    }

    val symbol: String
        get() {
            val roman = arrayOf("I", "II", "III", "IV", "V", "VI", "VII")[Math.floorMod(degree, 7)]
            val pcs = degrees.map { key.degreeToMidi(it) - key.degreeToMidi(degree) }
            val minorThird = pcs[1] == 3
            val dim = minorThird && pcs[2] == 6
            val base = if (minorThird) roman.lowercase() else roman
            return base + (if (dim) "°" else "") + (if (seventh) "7" else "")
        }
}

object KeyFinder {
    // Krumhansl-Kessler key profiles.
    private val MAJOR_PROFILE = doubleArrayOf(6.35, 2.23, 3.48, 2.33, 4.38, 4.09, 2.52, 5.19, 2.39, 3.66, 2.29, 2.88)
    private val MINOR_PROFILE = doubleArrayOf(6.33, 2.68, 3.52, 5.38, 2.60, 3.53, 2.54, 4.75, 3.98, 2.69, 3.34, 3.17)

    /**
     * Finds the best key for a set of (fractional midi, weight) observations.
     * Ties are broken toward keys whose tonic is the final note (melodies tend to end home).
     */
    fun find(pitches: List<Pair<Double, Double>>, lastPitch: Double?): Key {
        val hist = DoubleArray(12)
        for ((p, w) in pitches) hist[Math.floorMod(p.roundToInt(), 12)] += w
        var best = Key(0, Mode.MAJOR)
        var bestScore = Double.NEGATIVE_INFINITY
        val lastPc = lastPitch?.let { Math.floorMod(it.roundToInt(), 12) }
        for (tonic in 0 until 12) {
            for (mode in Mode.entries) {
                val prof = if (mode == Mode.MAJOR) MAJOR_PROFILE else MINOR_PROFILE
                var score = correlation(hist) { i -> prof[Math.floorMod(i - tonic, 12)] }
                // Autotune snaps to the scale, so strongly prefer keys that contain what was sung.
                val total = hist.sum()
                if (total > 0) {
                    var outside = 0.0
                    for (pc in 0 until 12) {
                        if (!mode.intervals.contains(Math.floorMod(pc - tonic, 12))) outside += hist[pc]
                    }
                    score -= 1.2 * outside / total
                }
                if (lastPc == tonic) score += 0.05
                if (mode == Mode.MAJOR) score += 0.01 // slight preference for major
                if (score > bestScore) {
                    bestScore = score; best = Key(tonic, mode)
                }
            }
        }
        return best
    }

    private fun correlation(a: DoubleArray, b: (Int) -> Double): Double {
        val ma = a.average()
        val bv = DoubleArray(12) { b(it) }
        val mb = bv.average()
        var num = 0.0; var da = 0.0; var db = 0.0
        for (i in 0 until 12) {
            num += (a[i] - ma) * (bv[i] - mb)
            da += (a[i] - ma) * (a[i] - ma)
            db += (bv[i] - mb) * (bv[i] - mb)
        }
        return if (da == 0.0 || db == 0.0) 0.0 else num / Math.sqrt(da * db)
    }
}
